```js
const { test } = require("node:test");
const assert = require("node:assert");
const { execFileSync, spawnSync } = require("node:child_process");
const path = require("path");

const CLI = path.join(__dirname, "..", "cli.js");
function run(args) {
  return spawnSync("node", [CLI, ...args], { encoding: "utf8" });
}

test("--upper uppercases", () => {
  const r = run(["--upper", "hello"]);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout.trim(), "HELLO");
});

test("--repeat 1 prints one line", () => {
  const r = run(["--upper", "--repeat", "1", "hi"]);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout.trim().split("\n").length, 1);
});

test("--repeat 3 prints three lines", () => {
  const r = run(["--upper", "--repeat", "3", "hi"]);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout.trim().split("\n").length, 3);
  assert.strictEqual(r.stdout.trim(), "HI\nHI\nHI");
});

test("--repeat 0 errors", () => {
  const r = run(["--upper", "--repeat", "0", "hi"]);
  assert.notStrictEqual(r.status, 0);
});

test("--repeat negative errors", () => {
  const r = run(["--upper", "--repeat", "-2", "hi"]);
  assert.notStrictEqual(r.status, 0);
});

test("--repeat non-numeric errors", () => {
  const r = run(["--upper", "--repeat", "banana", "hi"]);
  assert.notStrictEqual(r.status, 0);
});

test("missing text errors", () => {
  const r = run(["--upper"]);
  assert.notStrictEqual(r.status, 0);
});
```

